Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 10000000;
const int MAXN = 210;
const int MAXE = 21000;

struct Arc { int to, cap; } arc[MAXE];
int nxtArc[MAXE], headArc[MAXN], arcCnt;

void add_arc(int u, int v, int w) {
    arc[arcCnt].to = v; arc[arcCnt].cap = w; nxtArc[arcCnt] = headArc[u]; headArc[u] = arcCnt++;
    arc[arcCnt].to = u; arc[arcCnt].cap = 0; nxtArc[arcCnt] = headArc[v]; headArc[v] = arcCnt++;
}

int S, T;
int distTo[MAXN], curArc[MAXN], gapCnt[MAXN], inQueue[MAXN], parentNode[MAXN];

int max_flow(int src, int sink) {
    memset(curArc, -1, sizeof(curArc));
    memset(parentNode, -1, sizeof(parentNode));

    queue<int> que;
    que.push(sink);
    inQueue[sink] = 1;
    gapCnt[0]++;
    distTo[sink] = 0;

    while (!que.empty()) {
        int u = que.front();
        que.pop();
        for (int i = headArc[u]; i != -1; i = nxtArc[i]) {
            int v = arc[i].to;
            if (!inQueue[v]) {
                inQueue[v] = 1;
                que.push(v);
                distTo[v] = distTo[u] + 1;
                gapCnt[distTo[v]]++;
                curArc[v] = headArc[v];
            }
        }
    }

    int low = INF, u = src, ans = 0;
    parentNode[src] = src;

    while (distTo[src] < sink) {
        bool advanced = false;
        int i = curArc[u];

        while (i != -1) {
            if (arc[i].cap && distTo[arc[i].to] + 1 == distTo[u]) {
                advanced = true;
                low = min(low, arc[i].cap);
                parentNode[arc[i].to] = u;
                curArc[u] = i;
                u = arc[i].to;

                if (u == sink) {
                    while (u != src) {
                        u = parentNode[u];
                        arc[curArc[u]].cap -= low;
                        arc[curArc[u] ^ 1].cap += low;
                    }
                    ans += low;
                    low = INF;
                }
                break;
            }
            i = nxtArc[i];
            curArc[u] = i;
        }

        if (advanced) continue;

        int mindis = sink + 1;
        for (int i = headArc[u]; i != -1; i = nxtArc[i]) {
            if (arc[i].cap && mindis > distTo[arc[i].to]) {
                mindis = distTo[arc[i].to];
                curArc[u] = i;
            }
        }

        gapCnt[distTo[u]]--;
        if (gapCnt[distTo[u]] == 0) return ans;
        distTo[u] = mindis + 1;
        gapCnt[distTo[u]]++;
        u = parentNode[u];
    }

    return ans;
}

char gridA[12][12], gridB[12][12];
int startCnt[12][12], endNeed[12][12], stones[62][12][12];
int reachable[62][12][12][12][12];
int seen[12][12];
int moves[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, timeLimit;

void expandStones() {
    for (int k = 1; k <= timeLimit; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (stones[k-1][i][j] == 1) {
                    stones[k][i][j] = 1;
                } else if (stones[k-1][i][j] == 2) {
                    stones[k][i][j] = 2;
                } else {
                    for (int z = 0; z < 4; ++z) {
                        int nx = i + moves[z][0];
                        int ny = j + moves[z][1];
                        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                            if (stones[k-1][nx][ny] == 2) {
                                stones[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

void walk(int sx, int sy, int x, int y, int k) {
    seen[x][y] = 1;
    reachable[k][sx][sy][x][y] = 1;
    if (k >= timeLimit || stones[k][x][y]) return;
    for (int z = 0; z < 4; ++z) {
        int nx = x + moves[z][0];
        int ny = y + moves[z][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !seen[nx][ny]) {
            if (stones[k][nx][ny]) continue;
            walk(sx, sy, nx, ny, k + 1);
        }
    }
}

int main() {
    scanf("%d%d", &n, &timeLimit);

    for (int i = 1; i <= n; ++i) {
        scanf("%s", gridA[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (gridA[i][j] == 'Z') stones[0][i][j] = 2;
            else if (gridA[i][j] == 'Y') stones[0][i][j] = 1;
            else startCnt[i][j] = gridA[i][j] - '0';
        }
    }

    for (int i = 1; i <= n; ++i) {
        scanf("%s", gridB[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (gridB[i][j] >= '0' && gridB[i][j] <= '9')
                endNeed[i][j] = gridB[i][j] - '0';
        }
    }

    expandStones();

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (startCnt[i][j]) {
                memset(seen, 0, sizeof(seen));
                walk(i, j, i, j, 0);
            }

    for (int k = 1; k <= timeLimit; ++k)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int nx = 1; nx <= n; ++nx)
                    for (int ny = 1; ny <= n; ++ny)
                        reachable[k][x][y][nx][ny] += reachable[k-1][x][y][nx][ny];

    S = 0;
    T = n * n * 2 + 1;
    memset(headArc, -1, sizeof(headArc));
    arcCnt = 0;

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_arc(S, (i-1)*n + j, startCnt[i][j]);

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_arc(n*n + (i-1)*n + j, T, endNeed[i][j]);

    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int nx = 1; nx <= n; ++nx)
                for (int ny = 1; ny <= n; ++ny)
                    if (startCnt[x][y] && endNeed[nx][ny]) {
                        if (reachable[timeLimit][x][y][nx][ny])
                            add_arc((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                    }

    int ans = max_flow(S, T);
    printf("%d\n", ans);
    return 0;
}
